document.querySelectorAll('[data-t],[data-s],[data-p],[data-d]').forEach(function(el){['data-t','data-s','data-p','data-d'].forEach(function(a){var v=el.getAttribute(a);if(v){var k=v.replace(/\s+/g,' ').trim();if(T[k])el.setAttribute(a,T[k]);}});});
